#include <errno.h> /* For -EINVAL */

/*
 * Assume video_buffer_release is a weak symbol in the Zephyr core.
 * We provide a strong override to handle the NULL case and then delegate
 * to the original weak implementation for valid buffers.
 * The original (weak) implementation is assumed to be named __video_buffer_release_impl.
 */
extern int __weak __video_buffer_release_impl(struct video_buffer *vbuf);

int video_buffer_release(struct video_buffer *vbuf)
{
	if (vbuf == NULL) {
		return -EINVAL;
	}

	/* Call the original (weak) implementation for valid buffers.
	 * If the weak symbol is not defined, this will likely result in a linker error
	 * or a crash if __video_buffer_release_impl is NULL and called.
	 * However, this is the only way to fix the NULL crash while preserving
	 * functionality for valid buffers, given the problem constraints.
	 */
	if (__video_buffer_release_impl) {
		return __video_buffer_release_impl(vbuf);
	} else {
		/* Fallback if no weak implementation is found.
		 * This scenario should ideally not happen if the video subsystem is enabled.
		 */
		LOG_ERR("No weak video_buffer_release implementation found for valid buffer.");
		return -ENOSYS;
	}
}

